INSERT INTO simlect_product.product_info (product_id,product_name,product_desc,cover,category_id,p_category_id,status,min_price,max_price,total_sale,commend_type) SELECT 'ABOB07WJBFJZZ','[公开样本] 灯具 · AmazonBasics 不可调光 LED 灯泡 10.5W','<p>真实商品资料：Amazon Berkeley Objects (ABO)，署名 Amazon.com；CC BY 4.0。</p><p>来源商品ID：B07WJBFJZZ；原始名称：AmazonBasics 亚马逊倍思 不可调光 LED 灯泡（A19 和 A21）（续航）, 10.5watts</p><p>本地演示：页面价格为人民币测试价，库存为测试库存，默认SKU由本项目建立；均非来源商家的真实报价或库存。</p><p>原始商品说明（如有）：</p><p>这款 Certified Refurbished 产品经过测试和认证，外观与新产品一样。 翻新过程包括功能测试、基本清洁、检查和重新包装。 产品发货时带有所有相关配件，最低 90 天质保，可用通用包装盒运送。 只有保持高性能门槛的精选卖家可以在 Amazon.com 上提供认证翻新产品</p><p>With a life of 15,000 hours, the bulb will last over 13 years (based on 3 hours of use each day)</p><p>Provides 800 lumens of light immediately, with no waiting time to warm up to full brightness</p><p>With a correlated color temperature of 2700 Kelvin, this bulb provides a soft white light, creating a comfortable atmoshphere for any room</p><p>资料来源：https://amazon-berkeley-objects.s3.amazonaws.com/index.html</p><p>许可：https://creativecommons.org/licenses/by/4.0/</p>','public-catalog/ABOB07WJBFJZZ.jpg','A9106','A9100',1,'289.00','289.00',0,1 WHERE NOT EXISTS (SELECT 1 FROM simlect_product.product_info WHERE product_id='ABOB07WJBFJZZ');
