INSERT INTO simlect_product.product_info (product_id,product_name,product_desc,cover,category_id,p_category_id,status,min_price,max_price,total_sale,commend_type) SELECT 'ABOB07SRBSWZB','[公开样本] 灯具 · AmazonBasics GU10 可调光 LED 灯泡 10只装','<p>真实商品资料：Amazon Berkeley Objects (ABO)，署名 Amazon.com；CC BY 4.0。</p><p>来源商品ID：B07SRBSWZB；原始名称：AmazonBasics 亚马逊倍思 50W 相当于日光、可调光、10,000 小时寿命、MR16(GU10 灯座)LED 灯泡 | 10 个装</p><p>本地演示：页面价格为人民币测试价，库存为测试库存，默认SKU由本项目建立；均非来源商家的真实报价或库存。</p><p>原始商品说明（如有）：</p><p>灯泡的使用寿命为 10,000 小时,可持续使用 9 年以上(基于每天使用 3 小时)</p><p>立即提供 500 流明的光线,无需等待时间即可加热至全亮度</p><p>这款灯泡具有5000开尔文的相关色温,可模拟日光,为任何房间提供清脆的白光。</p><p>这款 LED 灯泡仅使用 7 瓦的能量,灯泡寿命比白炽灯相比节能高达 47.29 美元(基于 3 小时/天,11 美分/千瓦时,可能因速率和使用情况而有所不同)</p><p>资料来源：https://amazon-berkeley-objects.s3.amazonaws.com/index.html</p><p>许可：https://creativecommons.org/licenses/by/4.0/</p>','public-catalog/ABOB07SRBSWZB.jpg','A9106','A9100',1,'339.00','339.00',0,1 WHERE NOT EXISTS (SELECT 1 FROM simlect_product.product_info WHERE product_id='ABOB07SRBSWZB');
