INSERT INTO simlect_product.product_info (product_id,product_name,product_desc,cover,category_id,p_category_id,status,min_price,max_price,total_sale,commend_type) SELECT 'ABOB07HQTQLVX','[公开样本] 办公用品 · AmazonBasics 象牙色缎带 100m','<p>真实商品资料：Amazon Berkeley Objects (ABO)，署名 Amazon.com；CC BY 4.0。</p><p>来源商品ID：B07HQTQLVX；原始名称：AmazonBasics Satin Ribbon, 100 m, Ivory</p><p>本地演示：页面价格为人民币测试价，库存为测试库存，默认SKU由本项目建立；均非来源商家的真实报价或库存。</p><p>原始商品说明（如有）：</p><p>AmazonBasics is a collection of products created by combining quality and low prices for an overall focus on value. AmazonBasics offers a wide range of products in consumer electronics, headphones, Bluetooth speakers, wireless headphones, laptop bags, cases, laptop sleeves, earphones, iPhone charger cables, USC-C cables, HDMI cable, batteries, gaming headset, office supplies and more. AmazonBasics offers everyday items like HDMI cables, batteries, cables and headphones to gear up your electronics as well as office necessities like printer paper, shredders, pens, pencils, notebooks and more office supplies. Our lightning cables are created using the very latest Apple-issued connectors and ensure the fastest possible charge for any lightning powered IoS device. There is always something for all occasions at the best values. With a selection that continues to grow, the AmazonBasics brand is set to become a part of your daily convenience for electronics products and lifestyle. AmazonBasics products are sold with a limited warranty of one year.</p><p>100m Ribbon reel, wide ribbons with width of 3.8 cm, Made of Satin</p><p>Ideal for decorating cakes, push pops, cake pops, treats and treat bags</p><p>Premium Ivory color , use with amazonbasics boxes to create beautiful gifts for all occasions</p><p>Suitable for home, on-line sellers, office, wrapping parcels, industry etc</p><p>资料来源：https://amazon-berkeley-objects.s3.amazonaws.com/index.html</p><p>许可：https://creativecommons.org/licenses/by/4.0/</p>','public-catalog/ABOB07HQTQLVX.jpg','A9